CREATE TABLE text_demo (
    t TEXT,
    v VARCHAR(5),
    c CHAR(5)
);

INSERT INTO text_demo (t, v, c) VALUES ('hello world', 'hello', 'hi');

SELECT t, length(t) AS t_len,
       v, length(v) AS v_len,
       c, length(c) AS c_len,           -- 5, padded with spaces
       '[' || c || ']' AS padded
FROM text_demo;

-- length() counts characters, octet_length() counts bytes
SELECT length('café'), octet_length('café');   -- 4, 5 in UTF-8

-- VARCHAR(n) truncation is an error, not silent
INSERT INTO text_demo (v) VALUES ('toolong');
-- ERROR: value too long for type character varying(5)

CREATE TABLE customers (
    id        BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email     TEXT NOT NULL,
    country   TEXT NOT NULL CHECK (char_length(country) = 2),
    CONSTRAINT customers_email_format
        CHECK (email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[A-Za-z]{2,}$')
);

-- Case-insensitive uniqueness without citext:
CREATE UNIQUE INDEX customers_email_lower_uniq ON customers (lower(email));

INSERT INTO customers (email, country) VALUES ('Ada@Example.com', 'GB');
INSERT INTO customers (email, country) VALUES ('ada@example.com', 'GB');
-- ERROR: duplicate key value violates unique constraint "customers_email_lower_uniq"
